def wer(ref, hyp):
    r, h = ref.split(), hyp.split()
    # d[i][j] = word edit distance between first i ref and first j hyp words
    d = [[0] * (len(h) + 1) for _ in range(len(r) + 1)]
    for i in range(len(r) + 1):
        d[i][0] = i
    for j in range(len(h) + 1):
        d[0][j] = j
    for i in range(1, len(r) + 1):
        for j in range(1, len(h) + 1):
            cost = 0 if r[i-1] == h[j-1] else 1
            d[i][j] = min(d[i-1][j] + 1, d[i][j-1] + 1, d[i-1][j-1] + cost)
    return d[-1][-1] / len(r)     # errors divided by REFERENCE length

tests = [
    ("my account number is 4417", "my account number is 4471"),
    ("hello there", "hello there"),
    ("yes", "uh yes please thank you"),   # insertions can push WER above 100%
]
for ref, hyp in tests:
    print(f"ref={ref!r} hyp={hyp!r} WER={wer(ref, hyp):.0%}")
# Time O(R*H), space O(R*H) for R and H words
